#ifdef MACLOCK_COMBINED_SOURCE
static void reset_maze(ClockView &view, ScreensaverMode mode) { if (mode == ScreensaverMode::Maze) generate_maze(view); }
static bool update_maze(ClockView &view, uint32_t frame) { const uint8_t *walls = view.screensaver_state; const uint16_t *solution = reinterpret_cast<const uint16_t *>(view.screensaver_state + kMazeCells * 2 + kMazeCells * sizeof(uint16_t) * 2); for (uint16_t cell = 0; cell < kMazeCells; ++cell) { const int x = (cell % kMazeColumns) * 16, y = (cell / kMazeColumns) * 16; if (walls[cell] & 1U) line(view, x, y, x + 15, y); if (walls[cell] & 2U) line(view, x + 15, y, x + 15, y + 15); if (walls[cell] & 4U) line(view, x, y + 15, x + 15, y + 15); if (walls[cell] & 8U) line(view, x, y, x, y + 15); } const uint16_t length = static_cast<uint16_t>(view.screensaver_x[63]), progress = min<uint16_t>(length, static_cast<uint16_t>(frame / 2 + 1)); for (uint16_t i = 0; i < progress; ++i) { const uint16_t cell = solution[i]; fill_rect(view, (cell % kMazeColumns) * 16 + 6, (cell / kMazeColumns) * 16 + 6, 4, 4); } if (progress == length && frame > length * 2 + 90) { generate_maze(view); view.screensaver_extended_frame = 0; } return true; }
#endif
